// Auth handlers — Google OAuth2 flow.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"

	"github.com/chessgoddess/chessgoddess/internal/auth"
	"github.com/chessgoddess/chessgoddess/internal/config"
	"github.com/chessgoddess/chessgoddess/internal/model"
	"github.com/chessgoddess/chessgoddess/internal/repository"
	"github.com/gin-gonic/gin"
	"github.com/jackc/pgx/v5"
)

type AuthHandlers struct {
	service  *auth.Service
	userRepo *repository.UserRepository
	config   *config.Config
}

func NewAuthHandlers(service *auth.Service, userRepo *repository.UserRepository, cfg *config.Config) *AuthHandlers {
	return &AuthHandlers{service: service, userRepo: userRepo, config: cfg}
}

func (h *AuthHandlers) GetGoogleAuthURL(c *gin.Context) {
	state, err := h.service.GenerateState()
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to generate state"})
		return
	}

	secure := c.Request.TLS != nil || c.GetHeader("X-Forwarded-Proto") == "https"
	http.SetCookie(c.Writer, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		MaxAge:   3600,
		Path:     "/",
		HttpOnly: true,
		Secure:   secure,
		SameSite: http.SameSiteLaxMode,
	})
	c.JSON(http.StatusOK, gin.H{"url": h.service.GetAuthURL(state)})
}

func (h *AuthHandlers) GoogleCallback(c *gin.Context) {
	// Validate state cookie (CSRF protection).
	stateCookie, err := c.Cookie("oauth_state")
	if err != nil || stateCookie != c.Query("state") {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid oauth state"})
		return
	}
	http.SetCookie(c.Writer, &http.Cookie{
		Name:     "oauth_state",
		Value:    "",
		MaxAge:   -1,
		Path:     "/",
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})

	code := c.Query("code")
	if code == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
		return
	}

	token, err := h.service.ExchangeCode(c.Request.Context(), code)
	if err != nil {
		slog.Error("oauth code exchange failed", "err", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to exchange code"})
		return
	}

	// Fetch Google user info.
	client := h.service.GetHTTPClient(c.Request.Context(), token)
	resp, err := client.Get("https://www.googleapis.com/oauth2/v2/userinfo")
	if err != nil {
		slog.Error("failed to fetch google userinfo", "err", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to fetch user info"})
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		slog.Error("google userinfo returned non-200", "status", resp.StatusCode)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to fetch user info"})
		return
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to read user info"})
		return
	}

	var googleUser struct {
		ID        string `json:"id"`
		Email     string `json:"email"`
		Name      string `json:"name"`
		Picture   string `json:"picture"`
	}
	if err := json.Unmarshal(body, &googleUser); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to parse user info"})
		return
	}

	if googleUser.Email == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "google account has no email"})
		return
	}

	// Upsert user.
	user, err := h.userRepo.GetByGoogleID(c.Request.Context(), googleUser.ID)
	if err != nil {
		if !errors.Is(err, pgx.ErrNoRows) {
			slog.Error("db lookup failed", "err", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "database error"})
			return
		}
		user = &model.User{
			GoogleID:  googleUser.ID,
			Email:     googleUser.Email,
			Name:      googleUser.Name,
			AvatarURL: googleUser.Picture,
		}
		if err := h.userRepo.Create(c.Request.Context(), user); err != nil {
			slog.Error("failed to create user", "err", err)
			c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to create user"})
			return
		}
	}

	jwtToken, err := h.service.GenerateJWT(user.ID, user.Email, user.Name, user.AvatarURL)
	if err != nil {
		slog.Error("jwt generation failed", "err", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to generate token"})
		return
	}

	h.service.SetAuthCookie(c.Writer, jwtToken)
	c.Redirect(http.StatusFound, h.config.FrontendURL+"/?auth=success")
}

// Me returns the currently authenticated user (from the validated token).
func (h *AuthHandlers) Me(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{
		"user": gin.H{
			"id":         c.GetString("user_id"),
			"email":      c.GetString("email"),
			"name":       c.GetString("name"),
			"avatar_url": c.GetString("avatar_url"),
		},
	})
}

// Logout clears the auth cookie.
func (h *AuthHandlers) Logout(c *gin.Context) {
	h.service.ClearAuthCookie(c.Writer)
	c.JSON(http.StatusOK, gin.H{"message": "logged out"})
}

// Auth API calls — Google OAuth flow.
import { apiClient } from './client'

export interface AuthUser {
  id: string
  email: string
  name: string
  avatar_url: string
}

/** Get the Google OAuth URL to redirect the browser to. */
export async function getGoogleAuthURL(): Promise<{ url: string }> {
  const { data } = await apiClient.get('/auth/google/url')
  return data
}

/** Fetch the currently signed-in user; rejects (401) when not signed in. */
export async function getMe(): Promise<AuthUser> {
  const { data } = await apiClient.get('/auth/me')
  return data.user
}

/** Clear the auth session cookie. */
export async function logout(): Promise<void> {
  await apiClient.post('/auth/logout')
}

package auth

import (
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/chessgoddess/chessgoddess/internal/config"
)

func TestGenerateJWT(t *testing.T) {
	cfg := &config.Config{
		JWTSecret: "test-secret",
	}

	service := NewService(cfg)

	token, err := service.GenerateJWT("user1", "test@example.com", "Test User", "https://example.com/avatar.png")
	if err != nil {
		t.Fatalf("failed to generate JWT: %v", err)
	}

	if token == "" {
		t.Error("expected non-empty token")
	}
}

func TestValidateJWT_ValidToken(t *testing.T) {
	cfg := &config.Config{
		JWTSecret: "test-secret",
	}

	service := NewService(cfg)

	token, err := service.GenerateJWT("user1", "test@example.com", "Test User", "")
	if err != nil {
		t.Fatalf("failed to generate JWT: %v", err)
	}

	claims, err := service.ValidateJWT(token)
	if err != nil {
		t.Fatalf("failed to validate JWT: %v", err)
	}

	if claims.UserID != "user1" {
		t.Errorf("expected user_id 'user1', got '%s'", claims.UserID)
	}

	if claims.ExpiresAt == nil {
		t.Error("expected ExpiresAt to be set")
	}
	if claims.IssuedAt == nil {
		t.Error("expected IssuedAt to be set")
	}

	if claims.Email != "test@example.com" {
		t.Errorf("expected email 'test@example.com', got '%s'", claims.Email)
	}
}

func TestValidateJWT_InvalidToken(t *testing.T) {
	cfg := &config.Config{
		JWTSecret: "test-secret",
	}

	service := NewService(cfg)

	_, err := service.ValidateJWT("invalid-token")
	if err == nil {
		t.Error("expected error for invalid token")
	}
}

func TestValidateJWT_WrongSecret(t *testing.T) {
	cfg1 := &config.Config{
		JWTSecret: "secret1",
	}

	cfg2 := &config.Config{
		JWTSecret: "secret2",
	}

	service1 := NewService(cfg1)
	service2 := NewService(cfg2)

	token, err := service1.GenerateJWT("user1", "test@example.com", "Test User", "")
	if err != nil {
		t.Fatalf("failed to generate JWT: %v", err)
	}

	_, err = service2.ValidateJWT(token)
	if err == nil {
		t.Error("expected error for wrong secret")
	}
}

func TestGenerateState(t *testing.T) {
	cfg := &config.Config{
		JWTSecret: "test-secret",
	}

	service := NewService(cfg)

	state1, err := service.GenerateState()
	if err != nil {
		t.Fatalf("failed to generate state: %v", err)
	}

	state2, err := service.GenerateState()
	if err != nil {
		t.Fatalf("failed to generate state: %v", err)
	}

	if state1 == state2 {
		t.Error("expected different states")
	}
}

func TestSetAuthCookie(t *testing.T) {
	cfg := &config.Config{JWTSecret: "secret", Environment: "development"}
	svc := NewService(cfg)

	w := httptest.NewRecorder()
	svc.SetAuthCookie(w, "mytoken")

	cookies := w.Result().Cookies()
	var found bool
	for _, c := range cookies {
		if c.Name == "auth_token" && c.Value == "mytoken" {
			found = true
		}
	}
	if !found {
		t.Error("auth_token cookie not set")
	}
}

func TestClearAuthCookie(t *testing.T) {
	cfg := &config.Config{JWTSecret: "secret", Environment: "development"}
	svc := NewService(cfg)

	w := httptest.NewRecorder()
	svc.ClearAuthCookie(w)

	cookies := w.Result().Cookies()
	var found bool
	for _, c := range cookies {
		if c.Name == "auth_token" && c.MaxAge == -1 {
			found = true
		}
	}
	if !found {
		t.Error("auth_token clear cookie not set")
	}
}

func TestPackageLevelValidateJWT(t *testing.T) {
	cfg := &config.Config{JWTSecret: "secret"}
	svc := NewService(cfg)

	token, err := svc.GenerateJWT("u1", "a@b.com", "Name", "")
	if err != nil {
		t.Fatalf("GenerateJWT: %v", err)
	}

	claims, err := ValidateJWT(token, "secret")
	if err != nil {
		t.Fatalf("ValidateJWT: %v", err)
	}
	if claims.UserID != "u1" {
		t.Errorf("want u1, got %s", claims.UserID)
	}
}

func TestPackageLevelValidateJWT_WrongSecret(t *testing.T) {
	cfg := &config.Config{JWTSecret: "secret"}
	svc := NewService(cfg)

	token, _ := svc.GenerateJWT("u1", "a@b.com", "Name", "")
	_, err := ValidateJWT(token, "wrongsecret")
	if err == nil {
		t.Error("expected error for wrong secret")
	}
}

func TestPackageLevelValidateJWT_InvalidAlgorithm(t *testing.T) {
	// Ensure unexpected signing method is rejected.
	_, err := ValidateJWT(strings.Repeat("a", 200), "secret")
	if err == nil {
		t.Error("expected error for garbage token")
	}
}

